/**
 * Wails v3 bridge — wraps the statically generated bindings for the bound
 * core.App service (frontend/bindings/github.com/CodeNeow/llama-cpp-desktop,
 * regenerated by `wails3 generate bindings` whenever bound methods change).
 * Each exported wrapper keeps the exact signature and return-value shape it
 * had in the v2 window.go bridge era, so frontend consumers and the vitest
 * suites (which mock this module) stay unchanged. The `core` namespace comes
 * from the Go package core/ that hosts the App struct.
 */

import type { MonitorStatus } from './lib/monitor'
import type { ServerLogEntry } from './lib/serverLog'

import * as bindings from '../bindings/github.com/CodeNeow/llama-cpp-desktop/core/app'

// The generated bindings are statically imported, so unlike the v2
// window.go bridge there is no runtime availability probe: standalone
// (vite dev only) the calls fail at fetch time instead of throwing here.

function app(): any {
  // Untyped on purpose: the wrappers below declare their own precise return
  // types, keeping call sites and mocks byte-compatible with the v2 era.
  return bindings
}

// ─── Config ─────────────────────────────────────────────────────

export async function getConfig(): Promise<{ theme: string; llamaCppDir: string; modelsDir: string; llamaCppDownloadDir?: string; modelDownloadDir?: string; downloadSource: string; language: string; resolvedLanguage: 'zh' | 'en'; trayEnabled: boolean; apiRouteMode?: boolean; sidebarCollapsed?: boolean; onboardingDismissed?: boolean }> {
  return app().GetConfig()
}

export async function setTheme(theme: string): Promise<void> {
  return app().SetTheme(theme)
}

// Set the sidebar collapsed/expanded preference (pure UI state, no window-related side effects)
export async function setSidebarCollapsed(collapsed: boolean): Promise<void> {
  return app().SetSidebarCollapsed(collapsed)
}

// Dismiss the Home page quick-start checklist ("Don't show again" or auto-completed):
// pure UI preference persisted via the backend config's onboardingDismissed field.
export async function setOnboardingDismissed(dismissed: boolean): Promise<void> {
  return app().SetOnboardingDismissed(dismissed)
}

// Set the Windows system tray toggle (settings item rendered on Windows only; on other
// platforms the backend just persists without starting/stopping anything). systray cannot
// be started twice in one process: once disabled it stays disabled until the app restarts.
export async function setTrayEnabled(enabled: boolean): Promise<void> {
  return app().SetTrayEnabled(enabled)
}

// Toggle API-route (headless) mode (settings item rendered on Windows only). Enabling
// persists the preference, hands the running llama-server over, relaunches the app in
// headless mode (tray + llama-server only, no GUI/WebView2) and quits — the service
// keeps serving the OpenAI API without interruption. From headless, the tray "Show Main
// Window" item returns to GUI mode. On success this call never resolves visibly in the
// GUI (the app quits); failures reject for inline error display.
export async function setApiRouteMode(enabled: boolean): Promise<void> {
  return app().SetApiRouteMode(enabled)
}

// Set the UI language preference ("zh" | "en" | "auto"); the backend returns the effective
// resolvedLanguage (zh/en; auto is resolved from system detection), which store uses to
// refresh the UI copy
export async function setLanguage(language: string): Promise<string> {
  return app().SetLanguage(language)
}

