// Auto-tune the model's inference parameters: the backend reads the model's GGUF
// metrics, snapshots GPU/CPU/RAM, computes optimal llama-server options and
// persists them through the same validation path as saveModelConfig, returning
// the applied ModelConfig
export async function tuneModelConfig(modelID: string): Promise<any> {
  return app().TuneModelConfig(modelID)
}

// ModelBenchResult mirrors the backend core.ModelBenchResult: the measured
// token-generation throughput (tgTps) plus the effective parameters the
// llama-bench run used (ngl as reported, threads where 0 = auto/omitted,
// usedCpuMoe=false when the run fell back to no cpu-moe flags) and the
// wall-clock duration of the measured run (elapsedS)
export interface ModelBenchResult {
  tgTps: number
  ngl: string
  threads: number
  usedCpuMoe: boolean
  elapsedS: number
}

// Deep-benchmark the model's real decode speed with the llama-bench binary
// installed next to llama-server, using the model's currently saved config.
// The run loads the full model and may take minutes — user-triggered only,
// single-flight on the backend (a concurrent second call waits).
export async function benchmarkModel(modelID: string): Promise<ModelBenchResult> {
  return app().BenchmarkModel(modelID)
}

// ─── Server ──────────────────────────────────────────────────────

// ServerConfig mirrors the backend core.ServerConfig: accessMode is the service access
// scope ("local" | "lan"), host is the actual listen address derived from accessMode,
// apiKey is the optional llama-server bearer token (empty = no authentication),
// deviceId is the serving-GPU selection (stable nvidia-smi UUID; empty = auto, default CUDA device).
export interface ServerConfig {
  accessMode: string
  host: string
  port: number
  maxModels: number
  cacheRam: number
  apiKey: string
  deviceId: string
}

export async function getServerConfig(): Promise<ServerConfig> {
  return app().GetServerConfig()
}

export async function saveServerConfig(cfg: ServerConfig): Promise<void> {
  return app().SaveServerConfig(cfg)
}

export async function getServerStatus(): Promise<{ running: boolean; log: string[] }> {
  return app().GetServerStatus()
}

// Incremental server-log fetch: returns the ring entries appended since the
// given cursor (seq >= since; 0 = everything retained) plus the next cursor
// value to pass on the following call. Lines already evicted from the backend
// ring cannot be recovered — when next - since exceeds the ring cap the
// caller must refetch from 0 (see lib/serverLog.ts).
export async function getServerLogsSince(since: number): Promise<{ entries: ServerLogEntry[]; next: number }> {
  return app().GetServerLogsSince(since)
}

